'use strict';
/* Motor próprio: PWA estático, sem dependências de rede. */
const IS_PHASER_PREVIEW=document.documentElement.dataset.phaserPreview==='true';
const SAVE_KEY=IS_PHASER_PREVIEW?'thargrid_phaser_preview_save_v1':'thargrid_siege_save_v1';
const META_KEY=IS_PHASER_PREVIEW?'thargrid_phaser_preview_meta_v1':'thargrid_siege_meta_v1';
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));const rnd=(a,b)=>ThargridCore.integer(a,b);
const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);const fmtObj=obj=>Object.entries(obj).map(([k,v])=>`${RESN[k]?.[0]||k} ${v}`).join(' · ');
const RESN={gold:['🪙','Moedas'],food:['🍞','Alimento'],wood:['🪵','Madeira'],ore:['⛏️','Minério'],stone:['🪨','Pedra'],mana:['🔮','Essência'],hope:['✦','Moral'],herbs:['🌿','Ervas']};
const frontIdx=n=>FRONTS.findIndex(f=>f.id===n);
const defaultHero=d=>({...d,level:1,xp:0,alive:true,injured:0,fatigue:0,training:{atk:0,def:0,spd:0,vit:0,mag:0},professions:{[d.craft]:1},learned:[...CLASSES[d.klass].initial],hp:d.hp+CLASSES[d.klass].hp,mp:d.mp+CLASSES[d.klass].mp,status:{},barrier:0,used:false,personalDone:false});
function fresh(difficulty='normal'){
 const h={};HEROES.forEach(x=>h[x.id]=defaultHero(x));
 return {version:1,day:1,mode:'management',tab:'council',difficulty,orders:3,spent:0,res:{gold:150,food:158,wood:117,ore:92,stone:95,mana:77,hope:68,herbs:3},projects:{},fronts:[1,1,1,1],party:['brunna','dara','eirik','serena'],heroes:h,flags:{},quests:{},relics:[],inventory:{tonic:6,ether:4,phoenix:2,antidote:2},unlocked:['warden','ranger','mage','cleric'],journal:[{day:1,text:'Os sinos de Thargrid soam. A Rainha envia seus primeiros batedores.'}],battle:null,settled:false,offline:false,policy:'refugees',victories:0,casualties:0,history:[],gameOverReason:'',lastRewards:null};
}
let S=null;let battleSelect=null;let modalState=null;let toastTimeout=null;let availableOffline=false;
function log(text){S.journal.unshift({day:S.day,text});S.journal=S.journal.slice(0,160)}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(S))}catch(e){console.warn('save failed',e)}}
function load(){try{const data=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(data&&data.version===1&&data.heroes&&data.res&&Number.isInteger(data.day)){S=data;return true}}catch(e){console.warn(e)}return false}
function hero(id){return S.heroes[id]};function aliveHeroes(){return Object.values(S.heroes).filter(h=>h.alive&&(!h.unlock||S.flags[h.unlock]));}
function allHeroes(){return Object.values(S.heroes).filter(h=>!h.unlock||S.flags[h.unlock]);}
function isReady(h){return h&&h.alive&&(!h.unlock||S.flags[h.unlock]);}
function maxHP(h){let cls=CLASSES[h.klass];return Math.max(35,Math.round(h.hpBase||h.hpNatural||((HEROES.find(e=>e.id===h.id)||h).hp)+cls.hp+(h.level-1)*11+(h.training?.vit||0)*8+(h.personalDone?8:0)))}
function maxMP(h){let cls=CLASSES[h.klass];let base=(HEROES.find(e=>e.id===h.id)||h).mp;return Math.max(7,base+cls.mp+(h.level-1)*3+(h.training?.mag||0)*5+(S.relics.includes('codex')&&h.id==='eirik'?15:0))}
function stat(h,k){let cls=CLASSES[h.klass];let base=HEROES.find(e=>e.id===h.id)||h;const relBonus={brunna:{def:4},dara:{atk:6,spd:3},eirik:{mag:8},serena:{mag:6},gorun:{atk:7},brom:{atk:7}};
 let rb=0;if(S.relics.includes('hammer')&&h.id==='gorun'&&k==='atk')rb+=7;if(S.relics.includes('axe')&&h.id==='brom'&&k==='atk')rb+=7;if(S.relics.includes('bow')&&h.id==='dara'&&(k==='atk'||k==='spd'))rb+=(k==='atk'?6:3);if(S.relics.includes('codex')&&h.id==='eirik'&&k==='mag')rb+=8;if(S.relics.includes('lamp')&&h.id==='serena'&&k==='mag')rb+=6;if(S.relics.includes('banner')&&k==='def')rb+=4;
 let up=k==='atk'?2:k==='mag'?1.5:k==='def'?1.3:k==='spd'?.55:0;
 return Math.round(base[k]+cls[k]+(h.level-1)*up+(h.training?.[k]||0)*2+(h.personalDone?3:0)+rb+(S.projects.forge&&k==='atk'?S.projects.forge*2:0));
}
function statusText(h){let a=[];if(!h.alive)a.push('MORTO');if(h.injured)a.push('Ferido');if(h.fatigue>65)a.push('Exausto');else if(h.fatigue>32)a.push('Cansado');return a.join(' · ')}
function injuryLoss(h){return Math.ceil((h.injured?3:0)+h.fatigue/23)}
function hasCost(cost){return Object.entries(cost).every(([k,v])=>(S.res[k]||0)>=v)}
function charge(cost){if(!hasCost(cost))return false;for(const [k,v] of Object.entries(cost))S.res[k]-=v;return true}
function grant(cost){for(const [k,v] of Object.entries(cost||{}))S.res[k]=(S.res[k]||0)+v;S.res.hope=clamp(S.res.hope,0,100)}
function notify(msg){const x=document.getElementById('toast');if(x)x.remove();let d=document.createElement('div');d.className='toast';d.id='toast';d.textContent=msg;document.body.append(d);clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>d.remove(),3200)}
function spendOrder(h){if(S.orders<=0){notify('As três ordens do dia foram utilizadas.');return false}if(h&&h.used){notify(`${h.name} já cumpriu uma tarefa hoje.`);return false}S.orders--;S.spent++;if(h)h.used=true;return true}
function gainXP(h,n){if(!h||!h.alive)return;h.xp+=Math.round(n);let up=0;while(h.level<26&&h.xp>=xpNeed(h.level)){h.xp-=xpNeed(h.level);h.level++;up++;h.hp=Math.min(maxHP(h),h.hp+12);h.mp=Math.min(maxMP(h),h.mp+4)}if(up)log(`${h.name} avança ${up} nível(is), alcançando o nível ${h.level}.`)}
function xpNeed(lvl){return 48+lvl*29}
function goTab(t){S.tab=t;save();render()}
function projectCost(p){const lev=S.projects[p.id]||0;return Object.fromEntries(Object.entries(p.cost).map(([k,v])=>[k,Math.round(v*(1+lev*.8))]))}
function construct(id){let p=PROJECTS.find(x=>x.id===id);if(!p)return;let n=S.projects[id]||0;if(n>=p.max){notify('Projeto concluído no nível máximo.');return}let cost=projectCost(p);if(!hasCost(cost)){notify('Recursos insuficientes.');return}if(!spendOrder())return;charge(cost);S.projects[id]=n+1;log(`Os trabalhadores erguem ${p.name}, nível ${n+1}. ${p.desc}`);save();render()}
function frontCost(idx){return {stone:20+S.fronts[idx]*12,ore:14+S.fronts[idx]*10,gold:20+S.fronts[idx]*9}}
function reinforce(idx){if(idx<0||idx>=4)return;if(S.fronts[idx]>=5)return notify('Este acesso já está no nível máximo.');let cost=frontCost(idx);if(!hasCost(cost))return notify('Recursos insuficientes.');if(!spendOrder())return;charge(cost);S.fronts[idx]++;log(`Os clãs reforçam ${FRONTS[idx].id} para o nível ${S.fronts[idx]}.`);save();render()}
function train(id,which){let h=hero(id);if(!isReady(h)||h.used)return notify('Herói indisponível para treino.');if(h.fatigue>85)return notify('Herói exausto. Precisa recuperar-se.');let cost={food:4,gold:8+(h.training[which]||0)*4};if(!hasCost(cost))return notify('Faltam suprimentos para o treino.');if(!spendOrder(h))return;charge(cost);h.training[which]=(h.training[which]||0)+1;h.fatigue=clamp(h.fatigue+16-(S.projects.guild||0)*2,0,100);if(which==='vit')h.hp=Math.min(maxHP(h),h.hp+8);log(`${h.name} treinou ${({atk:'Força',def:'Defesa',spd:'Agilidade',vit:'Vigor',mag:'Concentração'})[which]}.`);save();closeModal();render()}
function study(id,skillId){let h=hero(id),sk=SKILLS[skillId];if(!isReady(h)||h.used||!sk)return notify('Não é possível estudar agora.');if(h.learned.includes(skillId))return notify('Essa técnica já foi aprendida.');if(h.level<(sk.level||1))return notify('Nível insuficiente.');let lvl=S.projects.library||0;if(lvl<1)return notify('Construa o Arquivo de Runas primeiro.');let cost={mana:7+3*(sk.level||1),gold:12+2*(sk.level||1)};if(!hasCost(cost))return notify('Faltam recursos para o estudo.');if(!spendOrder(h))return;charge(cost);h.learned.push(skillId);h.fatigue=clamp(h.fatigue+13,0,100);gainXP(h,7+3*(S.projects.guild||0));log(`${h.name} decifrou os princípios de ${sk.name}.`);save();closeModal();render()}
function learnJob(id,job){let h=hero(id);if(!isReady(h)||h.used)return notify('Herói indisponível.');if(!PROFESSIONS.find(j=>j.id===job))return;let lvl=h.professions[job]||0;if(lvl>=3)return notify('Profissão no máximo.');let cost={gold:16+lvl*12,food:5,mana:3};if(!hasCost(cost))return notify('Recursos insuficientes.');if(!spendOrder(h))return;charge(cost);h.professions[job]=lvl+1;h.fatigue=clamp(h.fatigue+14,0,100);gainXP(h,12+(S.projects.guild||0)*5);log(`${h.name} estudou o ofício ${PROFESSIONS.find(p=>p.id===job).name} (grau ${lvl+1}).`);save();closeModal();render()}
function switchClass(id,classId){let h=hero(id);if(!isReady(h)||h.used)return notify('Herói indisponível.');if(!S.unlocked.includes(classId))return notify('Esta classe ainda não foi liberada.');if(h.klass===classId)return notify('Já utiliza esta classe.');if(h.level<3)return notify('É preciso nível 3 para mudar de classe.');if(!(S.projects.guild||0))return notify('Construa Oficinas dos Ofícios primeiro.');let cost={gold:35,mana:12};if(!hasCost(cost))return notify('Recursos insuficientes.');if(!spendOrder(h))return;let oldMax=maxHP(h),oldMp=maxMP(h);charge(cost);h.klass=classId;for(let sk of CLASSES[classId].initial)if(!h.learned.includes(sk))h.learned.push(sk);h.hp=clamp(h.hp,1,maxHP(h));h.mp=clamp(h.mp,0,maxMP(h));h.fatigue=clamp(h.fatigue+15,0,100);log(`${h.name} conclui a mudança de classe para ${CLASSES[classId].name}.`);save();closeModal();render()}
function treat(id){let h=hero(id);if(!isReady(h)||h.used)return notify('Herói indisponível.');let cost={herbs:1,gold:14,food:3};if(!hasCost(cost))return notify('Faltam ervas ou outros recursos.');if(!spendOrder(h))return;charge(cost);h.hp=Math.min(maxHP(h),h.hp+Math.round(maxHP(h)*.45));h.mp=Math.min(maxMP(h),h.mp+Math.round(maxMP(h)*.35));h.fatigue=Math.max(0,h.fatigue-40);h.injured=0;log(`${h.name} recebeu cuidados intensivos na enfermaria.`);save();closeModal();render()}
const STORE={tonic:{name:'Tônico de vida',desc:'Cura 46 PV em combate.',cost:{gold:16,food:2}},ether:{name:'Éter rúnico',desc:'Restitui 24 MP em combate.',cost:{gold:24,mana:6}},phoenix:{name:'Cinza da Chama',desc:'Reergue um aliado caído em combate.',cost:{gold:46,mana:18}},antidote:{name:'Erva purificadora',desc:'Remove veneno, queimadura e maldições.',cost:{gold:16,herbs:1}}};
function buyItem(id){let i=STORE[id];if(!i)return;if(!charge(i.cost))return notify('Sem recursos suficientes.');S.inventory[id]=(S.inventory[id]||0)+1;save();render();notify(`${i.name} adquirido.`)}
function questAvailable(q){if(S.quests[q.id])return false;if(S.day<q.day)return false;if(q.hero&&!isReady(hero(q.hero)))return false;if(q.req&&!S.flags[q.req])return false;return true}
function questRun(qid,hid){let q=QUESTS.find(x=>x.id===qid);if(!q||!questAvailable(q))return notify('Missão indisponível.');let h=hero(hid);if(!isReady(h)||h.used)return notify('Herói indisponível.');if(q.hero&&q.hero!==hid)return notify('Esta é uma missão pessoal.');if(h.fatigue>89)return notify('Exaustão extrema impede esta expedição.');if(!spendOrder(h))return;let profi=Math.max(0,...Object.values(h.professions||{}));let success=ThargridCore.random()*100 < clamp(88+2*h.level+3*profi-(q.risk||0)*1.6,56,97);
 h.fatigue=clamp(h.fatigue+q.fatigue-(S.projects.scouts||0)*2,0,100);
 let hurt=clamp(rnd(0,q.risk||0)-(h.professions.medicina||0)*2,0,35);
 if(hurt>0)h.hp=Math.max(1,h.hp-hurt);
 if(h.hp/maxHP(h)<.35&&hurt>5)h.injured=2;
 if(success){S.quests[q.id]=true;S.flags[q.flag||q.id]=true;grant(q.reward);gainXP(h,q.xp+(S.projects.guild||0)*5);if(q.effect&&q.effect.startsWith('personal:')){h.personalDone=true;h.training.atk+=1;h.training.mag+=1}
 if(q.unlock){let [type,val]=q.unlock.split(':');if(type==='hero'){S.flags['found'+cap(val)]=true;S.flags[val==='gorun'?'foundGorun':val==='brom'?'foundBrom':val==='lyra'?'foundLyra':val==='noemi'?'foundNoemi':'foundTavio']=true;let target=hero(val);if(target){target.hp=maxHP(target);target.mp=maxMP(target)}}if(type==='classes'&&!S.unlocked.includes(val))S.unlocked.push(val);if(type==='hero'&&hero(val)&&!S.unlocked.includes(hero(val).klass))S.unlocked.push(hero(val).klass)}
 if(q.relic&&!S.relics.includes(q.relic))S.relics.push(q.relic);
 log(`MISSÃO CONCLUÍDA · ${q.title}: ${q.narrative}`);notify(`Missão concluída: ${q.title}`);
 }else{gainXP(h,Math.round(q.xp*.32));h.hp=Math.max(1,h.hp-rnd(3,10));h.injured=Math.max(h.injured,1);log(`MISSÃO FALHOU · ${q.title}. ${h.name} retorna ferido. A rota permanece aberta para nova tentativa.`);notify('A expedição falhou. Leia o diário para entender o risco.');}
 save();closeModal();render()}
function chooseParty(id){let h=hero(id);if(!isReady(h))return;let selected=S.party;let i=selected.indexOf(id);if(i>=0)selected.splice(i,1);else if(selected.length<4)selected.push(id);else return notify('A equipe aceita no máximo quatro heróis.');save();render()}
function raid(){return RAIDS[S.day-1]||RAIDS[RAIDS.length-1]}
function beginBattle(){publishCombatFeedback([]);if((S.day-1)%6===0&&!S.flags['council_'+Math.floor((S.day-1)/6)])return notify('O conselho precisa decidir o rumo do reino antes desta batalha.');if(!S.party.length)return notify('Escolha ao menos um defensor.');for(let id of S.party)if(!isReady(hero(id)))return notify('A equipe contém personagem indisponível.');let evt=raid();
 const foes=evt.foes.map((id,n)=>ThargridCore.enemyStats(MONSTERS[id],S.day,S.difficulty,'e'+n,id));
 const b={event:evt.day,foes,party:[...S.party],round:0,queue:[],ptr:0,active:null,logs:[`Dia ${S.day}: ${evt.title}`,evt.story],finished:false,major:evt.boss};S.battle=b;S.mode='battle';
 S.party.forEach(id=>{let h=hero(id);h.status={};h.barrier=0;});
 const idx=frontIdx(evt.front),fort=S.fronts[idx]||1;let protection=fort+(S.projects.barracks||0)+(S.projects.scouts||0)+Math.floor(Math.max(0,...aliveHeroes().map(h=>h.professions.fortificação||0))/2);
 if(protection>=2){S.party.forEach(id=>{let h=hero(id);h.barrier+=protection*3});b.logs.push(`As estruturas do setor concedem até ${protection*3} pontos de proteção inicial a cada herói.`)}
 if(protection<2+Math.floor((S.day-1)/10)){S.party.forEach(id=>{let h=hero(id);if(ThargridCore.random()<.43){h.hp=Math.max(1,h.hp-rnd(3,7+Math.floor(S.day/8)))}});b.logs.push(`A defesa do setor ${evt.front} cede antes do combate: a companhia recebe danos na aproximação.`)}else b.logs.push(`As fortificações do setor ${evt.front} protegem os defensores na aproximação.`);
 createRound();advanceTurn();save();render()}
function fighter(side,id){return side==='hero'?hero(id):S.battle.foes.find(e=>e.uid===id)}
function aliveUnit(side,id){let x=fighter(side,id);return !!x&&(side==='hero'?x.alive&&x.hp>0:x.hp>0&&!x.dead)}
function createRound(){
 const result=ThargridRounds.applyRoundStart(S,RAIDS[S.battle.event-1].hazard,{
   core:ThargridCore,effects:ThargridEffects,heroes:HEROES,classes:CLASSES
 });
 S=result.state;
 publishCombatFeedback(result.events,true);
}
function combatLog(s){let b=S.battle;if(!b)return;b.logs.unshift(s);b.logs=b.logs.slice(0,26)}
function effectStart(unit,side){
 const id=side==='hero'?unit.id:unit.uid;
 const result=ThargridEffects.applyTurnStart(S,side,id,{heroes:HEROES,classes:CLASSES});
 S=result.state;publishCombatFeedback(result.events,true);
}
function checkBattle(){let b=S.battle;if(!b)return true;if(!b.party.some(id=>hero(id).hp>0&&hero(id).alive)){gameOver(`Todos os defensores enviados para ${raid().front} morreram. A Rainha atravessou o setor e o Reino Sob a Montanha foi invadido no dia ${S.day}.`);return true}
 if(!b.foes.some(f=>f.hp>0)){victory();return true}return false}
function advanceTurn(){let b=S.battle;if(!b||b.finished)return;let guard=0;while(guard++<90){if(checkBattle())return;if(b.ptr>=b.queue.length){createRound();b=S.battle;if(b.round>65){combatLog('O cerco se prolonga e as tropas inimigas entram em fúria.')}}
 const it=b.queue[b.ptr++];if(!aliveUnit(it.side,it.id))continue;let u=fighter(it.side,it.id);let wasStunned=!!u.status.stun;effectStart(u,it.side);b=S.battle;u=fighter(it.side,it.id);if(!aliveUnit(it.side,it.id)){if(checkBattle())return;continue}
 if(wasStunned){combatLog(`${u.name} perde a vez por atordoamento.`);delete u.status.stun;continue}
 if(it.side==='hero'){b.active=it.id;b.logs=b.logs.slice(0,25);return}else{enemyAction(u);b=S.battle;if(checkBattle())return}}
}
function enemyAction(e){
 const result=ThargridEffects.applyEnemyAction(S,e.uid,{
   heroes:HEROES,classes:CLASSES,core:ThargridCore
 });
 S=result.state;publishCombatFeedback(result.events,true);
}
function physicalHeroDamage(h,sk,t){
 return ThargridCore.heroDamage({
  hero:h,skill:sk,target:t,attack:stat(h,'atk'),magic:stat(h,'mag'),
  forge:S.projects.forge||0,hazard:raid().hazard
 });
}
// Action validation and effect execution share the same save-compatible state.
let combatFeedback={seq:0,events:[]};
function publishCombatFeedback(events,append=false){
 const visible=events.filter(e=>e.type!=='log');
 combatFeedback={seq:combatFeedback.seq+1,events:append?[...combatFeedback.events,...visible].slice(-40):visible};
}
function doSkill(key,target){
 const plan=ThargridActions.planSkill(S,key,target,SKILLS,CLASSES);
 if(!plan.ok){if(plan.reason)notify(plan.reason);return}
 const outcome=ThargridEffects.applySkill(S,plan,key,{
   skills:SKILLS,classes:CLASSES,heroes:HEROES,core:ThargridCore,hazard:raid().hazard
 });
 S=outcome.state;
 publishCombatFeedback(outcome.events);
 battleSelect=null;closeModal();
 if(checkBattle()){save();render();return}
 advanceTurn();save();render();
}
function useCombatItem(key,target){
 const plan=ThargridActions.planItem(S,key,target);
 if(!plan.ok){if(plan.reason)notify(plan.reason);return}
 const outcome=ThargridEffects.applyItem(S,plan,key,{
   classes:CLASSES,heroes:HEROES,store:STORE
 });
 S=outcome.state;
 publishCombatFeedback(outcome.events);
 closeModal();advanceTurn();save();render();
}
function victory(){let b=S.battle;if(!b||b.finished)return;b.finished=true;S.mode='aftermath';S.victories++;let evt=raid();let gold=12+Math.floor(S.day*.90)+(S.projects.scouts||0)*4,ore=3+Math.floor(S.day/14);let reward={gold,ore,hope:evt.boss?5:1};grant(reward);
 let xp=23+S.day*2+(evt.boss?45:0);let dead=[];
 b.party.forEach(id=>{let h=hero(id);if(h.hp<=0){h.alive=false;dead.push(h.name);S.casualties++;return}gainXP(h,xp);h.fatigue=clamp(h.fatigue+15+(evt.boss?8:3),0,100);if(h.hp/maxHP(h)<.31)h.injured=Math.max(1,h.injured)});
 let idx=frontIdx(evt.front);let potential=Math.max(0,2+Math.floor((S.day-1)/10)-S.fronts[idx]-(S.projects.barracks||0));let damage=clamp(rnd(0,4)+potential*2+(evt.boss?2:0),0,18);S.res.hope=clamp(S.res.hope-(dead.length?dead.length*5:0)-Math.floor(damage/3),0,100);
 const chapter=Math.floor((S.day-1)/6);const repair={stone:2+Math.ceil(damage*.5)+Math.floor(chapter/2),ore:2+Math.floor(chapter*.65)+(evt.boss?5:0),wood:2+Math.floor(chapter/3)};let shortfall=0;for(const [k,n] of Object.entries(repair)){let taken=Math.min(S.res[k]||0,n);S.res[k]-=taken;shortfall+=n-taken;}if(shortfall){S.res.hope=clamp(S.res.hope-shortfall*2,0,100);log('Falta material para reparar os danos do cerco; a população perde confiança.')}if(damage>0)S.fronts[idx]=Math.max(0,S.fronts[idx]-(damage>=13?1:0));
 if(evt.boss)log(ACTS[evt.act].ending);
 log(`DEFESA VITORIOSA · ${evt.title}. ${evt.outcome} Recompensa: ${fmtObj(reward)}.${dead.length?' Tombaram: '+dead.join(', ')+'.':''}`);
 S.history.push({day:S.day,title:evt.title,dead:[...dead],reward});S.lastRewards={reward,xp,dead,evt:evt.day,damage,repair};save()}
function gameOver(text){S.gameOverReason=text;S.mode='gameover';S.battle.finished=true;log('DERROTA FINAL: '+text);save()}
function nextDay(){if(S.mode!=='aftermath')return;if(S.day>=60){S.mode='ending';log('Thargrid venceu os sessenta dias do cerco.');save();render();return}
 S.day++;S.orders=3;S.spent=0;S.party=S.party.filter(id=>isReady(hero(id)));for(const h of aliveHeroes()){h.used=false;h.status={};h.barrier=0;h.fatigue=Math.max(0,h.fatigue-(18+(S.projects.infirmary||0)*6));let rec=Math.round(8+(S.projects.sanctuary||0)*5+(S.projects.infirmary||0)*9+(h.professions.medicina||0)*2);h.hp=Math.min(maxHP(h),h.hp+rec);h.mp=Math.min(maxMP(h),h.mp+Math.round(5+(S.projects.library||0)*3));if(h.injured>0)h.injured--;}
 let gains={gold:8,food:7,wood:5,ore:4,stone:4,mana:3};for(const h of aliveHeroes()){gains.ore+=(h.professions.forja||0);gains.food+=2*(h.professions.botânica||0)+(h.professions.rastreamento||0);gains.mana+=2*(h.professions.arcanismo||0);gains.gold+=2*(h.professions.diplomacia||0);gains.hope=(gains.hope||0)+(h.professions.crônica||0);if((h.professions.medicina||0)&&S.day%3===0)gains.herbs=(gains.herbs||0)+1;}for(let p of PROJECTS)if(S.projects[p.id])for(let [k,v] of Object.entries(p.gain))gains[k]=(gains[k]||0)+v*S.projects[p.id];grant(gains);
 let upkeep=Math.max(6,8+aliveHeroes().length*2+Math.floor((S.day-1)/6)*2-(S.projects.granary||0)*2);S.res.food-=upkeep;S.res.food=Math.min(S.res.food,190+75*(S.projects.granary||0));
 if(S.res.food<0){S.res.food=0;S.res.hope=clamp(S.res.hope-8,0,100);aliveHeroes().forEach(h=>{h.fatigue=clamp(h.fatigue+10,0,100);h.hp=Math.max(1,h.hp-8)});log('Os celeiros ficaram vazios: fome e exaustão atingem os defensores.')}if(S.res.hope<24)aliveHeroes().forEach(h=>h.fatigue=clamp(h.fatigue+4,0,100));
 S.battle=null;S.mode='management';S.tab='council';if(S.day%6===1)log('NOVO ATO · '+ACTS[Math.floor((S.day-1)/6)].title+' — '+ACTS[Math.floor((S.day-1)/6)].intro);
 save();render()}
function cssFill(v,max,c='hp'){return `<div class="progress"><div class="fill ${c}" style="width:${clamp(Math.round(100*v/Math.max(1,max)),0,100)}%"></div></div>`}
function resourceStrip(){return `<div class="resources">${['gold','food','wood','ore','stone','mana'].map(k=>`<div class="resource" title="${RESN[k][1]}">${RESN[k][0]} <b class="n">${Math.floor(S.res[k])}</b></div>`).join('')}</div>`}
function hdr(){return `<header class="topbar"><div class="toprow spread"><div><div class="brand">CARCAÇA · O CERCO DE THARGRID</div><div class="daytitle">Dia ${S.day} <span style="font-size:12px;color:var(--mute);font-family:ui-sans-serif">/ 60</span></div></div><div style="text-align:right"><div class="tiny">Ordens disponíveis</div><div class="highlight bold">${S.orders} / 3</div></div></div>${resourceStrip()}</header>`}
function nav(){const arr=[['council','🏔️','Conselho'],['heroes','⚔️','Heróis'],['quests','📜','Missões'],['town','⚒️','Reino'],['codex','📖','Crônica']];return `<nav class="tabs">${arr.map(([id,ic,n])=>`<button class="tab ${S.tab===id?'active':''}" data-a="tab" data-v="${id}"><span>${ic}</span>${n}</button>`).join('')}</nav>`}
function renderCouncil(){let evt=raid(),index=frontIdx(evt.front),fort=S.fronts[index],power=fort+(S.projects.barracks||0)+(S.projects.scouts||0)+Math.floor(Math.max(0,...aliveHeroes().map(h=>h.professions.fortificação||0))/2);let relevant=ACTS[evt.act];let r=`<div class="eyebrow">${esc(relevant.title)}</div><h2 class="section">O Reino Sob a Montanha</h2>${(S.day-1)%6===0&&!S.flags['council_'+evt.act]?`<div class="card important"><div class="eyebrow">Conselho dos clãs e refugiados</div><h3>${esc(COUNCILS[evt.act].title)}</h3><p class="story">${esc(COUNCILS[evt.act].story)}</p><button class="btn green wide" data-a="council">Deliberar no conselho</button></div>`:''}<div class="card important"><div class="eyebrow">Ataque inevitável desta noite</div><h3>${esc(evt.title)}</h3><p class="story">${esc(evt.story)}</p><div class="chips"><span class="chip alert">${FRONTS[index].icon} ${esc(evt.front)}</span><span class="chip">${esc(evt.foes.length)} adversários</span>${evt.boss?'<span class="chip alert">CONFRONTO DECISIVO</span>':''}</div><p class="small" style="margin-top:10px"><strong>Informação dos vigias:</strong> ${esc(evt.hint)}</p></div><div class="twocol"><div class="card"><div class="tiny">Ânimo da população</div><div style="font-size:23px;color:${S.res.hope>35?'var(--jade)':'var(--red)'}">${S.res.hope}%</div>${cssFill(S.res.hope,100,'')}</div><div class="card"><div class="tiny">Fortificações do setor</div><div style="font-size:23px;color:var(--gold)">${power}</div><div class="small">Estrutura + quartel + vigias</div></div></div><div class="card"><div class="boxline"><div><h3>Preparação antes do sino</h3><div class="small">Treine, estude, construa ou envie heróis em missões. A cada noite, a Corte atacará.</div></div></div><div class="rule"></div><div class="chips"><span class="chip">${S.orders} ordens disponíveis</span><span class="chip">${aliveHeroes().length} defensores vivos</span><span class="chip">${S.relics.length} lendárias</span></div></div><button class="btn wide" data-a="prepare">⚔️ Organizar defesa da noite</button><div class="card soft" style="margin-top:11px"><div class="eyebrow">O preço da resistência</div><p>Os heróis continuam feridos e cansados de um dia para outro. Só o tempo, a enfermaria e o tratamento recuperam sua força. O ataque acontecerá mesmo quando faltarem recursos.</p></div>`;return r}
function heroMini(h,canChoose){const ready=isReady(h),pct=clamp(Math.floor(h.hp/maxHP(h)*100),0,100),cl=CLASSES[h.klass],chosen=S.party.includes(h.id);return `<div class="card"><div class="hero-card"><div class="hero-avatar ${!h.alive?'portrait-dead':''}">${cl.icon}</div><div class="hero-info"><div class="hero-head"><strong>${esc(h.name)}</strong><span class="badge">Nv ${h.level}</span></div><div class="hero-meta">${esc(cl.name)} · ${esc(h.tag)}</div><div class="metric-label" style="margin-top:5px"><span>PV ${h.hp} / ${maxHP(h)}</span><span>MP ${h.mp} / ${maxMP(h)}</span></div>${cssFill(h.hp,maxHP(h),'hp')}<div class="metric-label"><span>Cansaço ${h.fatigue}%</span><span class="${h.injured?'bad':'muted'}">${statusText(h)||'Apto'}</span></div>${cssFill(h.fatigue,100,'fatigue')}</div></div>${canChoose?`<button class="btn ${chosen?'green':'secondary'} small wide" data-a="party" data-v="${h.id}" ${ready?'':'disabled'}>${chosen?'✓ Na companhia':'Escolher defensor'}</button>`:''}</div>`}
function renderHeroes(){let list=allHeroes();return `<div class="eyebrow">A companhia</div><h2 class="section">Heróis, cicatrizes e ofícios</h2><p class="small">Cada herói pode executar uma tarefa durante o dia. O treino aumenta atributos; o estudo ensina técnicas e magia; os ofícios melhoram a sobrevivência da cidade. Ninguém é curado automaticamente ao fim de uma batalha.</p>${list.map(h=>`<div class="card"><div class="hero-card"><div class="hero-avatar ${!h.alive?'portrait-dead':''}">${CLASSES[h.klass].icon}</div><div class="hero-info"><div class="hero-head"><strong>${esc(h.name)}</strong><span class="badge">Nv ${h.level}</span></div><div class="hero-meta">${CLASSES[h.klass].name} · ${esc(h.tag)}</div><div class="small">${esc(h.bio)}</div><div class="metric-label"><span>PV ${h.hp}/${maxHP(h)} · MP ${h.mp}/${maxMP(h)}</span><span>XP ${h.xp}/${xpNeed(h.level)}</span></div>${cssFill(h.hp,maxHP(h),'hp')}${cssFill(h.mp,maxMP(h),'mp')}<div class="statusflag">${statusText(h)||'Disponível'}${h.used?' · Tarefa feita':''}</div><div class="tiny">ATQ ${stat(h,'atk')} · MAG ${stat(h,'mag')} · DEF ${stat(h,'def')} · VEL ${stat(h,'spd')}</div><div class="tiny">Ofícios: ${Object.entries(h.professions).map(([k,l])=>(PROFESSIONS.find(p=>p.id===k)?.name||k)+' '+l).join(', ')}</div></div></div><div class="btnrow" style="margin-top:10px"><button class="btn secondary small" data-a="heroaction" data-v="${h.id}" ${(!h.alive||h.used)?'disabled':''}>Desenvolver</button><button class="btn ghost small" data-a="herodetail" data-v="${h.id}">Ficha</button></div></div>`).join('')}`}
function renderQuests(){let av=QUESTS.filter(questAvailable);let pending=QUESTS.filter(q=>!S.quests[q.id]&&!questAvailable(q));let finished=QUESTS.filter(q=>S.quests[q.id]);return `<div class="eyebrow">Expedições facultativas</div><h2 class="section">Missões com consequências</h2><p class="small">Ir a uma missão consome uma ordem e o dia de trabalho do herói. Ele retorna antes do ataque da noite, mas pode estar exausto ou ferido. Missões pessoais exigem o herói indicado; expedições lendárias exigem pré-requisitos.</p><div class="chips"><span class="chip success">${av.length} disponíveis</span><span class="chip">${finished.length} concluídas</span><span class="chip">${pending.length} a descobrir</span></div><h3 class="subhead">Missões disponíveis</h3>${av.length?av.map(q=>`<div class="card ${q.kind==='lendária'?'important':''}"><div class="eyebrow">${q.kind==='lendária'?'✦ Artefato lendário':q.kind==='pessoal'?'◆ Missão pessoal':esc(q.kind)}</div><h3>${esc(q.title)}</h3><p class="story">${esc(q.desc)}</p><div class="small">Recompensas: ${fmtObj(q.reward)} · ${q.xp} XP · ${q.fatigue} cansaço</div>${q.hero?`<p class="small">Exige: ${esc(hero(q.hero).name)}</p>`:''}<button class="btn small wide" data-a="questopen" data-v="${q.id}" ${S.orders?'':'disabled'}>Enviar herói</button></div>`).join(''):'<div class="placeholder">Nenhuma missão disponível no momento. Novas expedições surgem ao longo do cerco e após encontros importantes.</div>'}<h3 class="subhead">Arquivos concluídos</h3>${finished.slice().reverse().map(q=>`<div class="entry"><div class="entry-title">✓ ${esc(q.title)}</div><div class="entry-text">${esc(q.narrative)}</div></div>`).join('')||'<p class="small">Nenhuma missão concluída ainda.</p>'}`}
function renderTown(){let current=raid();return `<div class="eyebrow">Economia de guerra</div><h2 class="section">Forjas, campos e projetos</h2><p class="small">Não há mapa para construir. Cada projeto possui três níveis de produção ou efeito e custa uma ordem de trabalho. Os recursos se renovam a cada amanhecer.</p><div class="card"><div class="boxline"><h3>Suprimentos da cidade</h3><span class="badge">Moral ${S.res.hope}%</span></div><div class="chips">${Object.keys(RESN).map(k=>`<span class="chip">${RESN[k][0]} ${RESN[k][1]}: ${S.res[k]||0}</span>`).join('')}</div></div><h3 class="subhead">Projetos do reino</h3><div class="projects">${PROJECTS.map(p=>{let n=S.projects[p.id]||0,c=projectCost(p);return `<div class="project"><div class="project-head"><span class="project-icon">${p.icon}</span><div class="flex1"><div class="project-title">${esc(p.name)} <span class="highlight">${n}/${p.max}</span></div><div class="small">${esc(p.desc)}</div></div></div><div class="project-detail">${esc(p.bonus)}</div><div class="boxline"><span class="cost">${n>=p.max?'Projeto máximo':fmtObj(c)}</span><button class="btn small" data-a="construct" data-v="${p.id}" ${(S.orders<=0||n>=p.max||!hasCost(c))?'disabled':''}>${n?'Melhorar':'Construir'}</button></div></div>`}).join('')}</div><h3 class="subhead">Quatro pontos vulneráveis</h3>${FRONTS.map((f,i)=>`<div class="card"><div class="boxline"><div class="flex1"><h3>${f.icon} ${esc(f.id)} · Nível ${S.fronts[i]}</h3><p>${esc(f.desc)}</p>${current.front===f.id?'<span class="chip alert">Alvo desta noite</span>':''}</div><button class="btn small secondary" data-a="front" data-v="${i}" ${(S.orders<=0||S.fronts[i]>=5||!hasCost(frontCost(i)))?'disabled':''}>Fortificar</button></div><div class="cost">${S.fronts[i]<5?fmtObj(frontCost(i)):'Defesa máxima'}</div></div>`).join('')}<h3 class="subhead">Armazém de suprimentos</h3>${Object.entries(STORE).map(([k,o])=>`<div class="card"><div class="boxline"><div class="flex1"><h3>${esc(o.name)} <span class="highlight">×${S.inventory[k]||0}</span></h3><p>${esc(o.desc)}</p><span class="cost">${fmtObj(o.cost)}</span></div><button class="btn small secondary" data-a="buy" data-v="${k}" ${hasCost(o.cost)?'':'disabled'}>Comprar</button></div></div>`).join('')}`}
function renderCodex(){let act=ACTS[Math.floor((S.day-1)/6)];return `<div class="eyebrow">Crônicas da resistência</div><h2 class="section">Memória contra o esquecimento</h2><div class="card important"><h3>${esc(act.title)}</h3><p class="story">${esc(act.intro)}</p></div><h3 class="subhead">Campanha</h3><div class="chips"><span class="chip success">${S.victories} dias defendidos</span><span class="chip alert">${S.casualties} baixas</span><span class="chip">${S.relics.length} relíquias</span></div><h3 class="subhead">Relíquias lendárias</h3>${S.relics.length?S.relics.map(id=>`<div class="card"><h3>${RELICS[id].icon} ${esc(RELICS[id].name)}</h3><p>${esc(RELICS[id].desc)}</p></div>`).join(''):'<p class="small">Ainda não encontrou artefatos lendários. Siga missões pessoais para revelar novas trilhas.</p>'}<h3 class="subhead">Diário de guerra</h3>${S.journal.slice(0,65).map(j=>`<div class="entry"><div class="entry-title">Dia ${j.day}</div><div class="entry-text">${esc(j.text)}</div></div>`).join('')}<h3 class="subhead">Segurança do progresso</h3><div class="btnrow"><button class="btn secondary small" data-a="export">Exportar save</button><button class="btn secondary small" data-a="import">Importar save</button></div><div class="small" style="margin-top:9px">Salvar ocorre automaticamente neste navegador. Exportar mantém uma cópia fora do armazenamento local.</div><h3 class="subhead">Créditos e regras</h3><div class="card"><p>Jogo autoral ambientado na Carcaça. ${esc(SOURCES_NOTE)} O sistema é inspirado no ritmo de RPGs de turnos, com mecânicas próprias e não contém regras integrais de D&D 5E.</p><p>As histórias do cerco são desdobramentos ficcionais da ambientação, preservando o passado conhecido de Thargrid e a ausência de Rayquaza após a queda de Voragar.</p></div>`}
function decideCouncil(index){const ai=Math.floor((S.day-1)/6),evt=COUNCILS[ai],opt=evt?.choices[index];if(!opt)return;if(S.flags['council_'+ai])return;const cost=opt.cost||{};if(!hasCost(cost))return notify('Faltam recursos para esta decisão.');charge(cost);grant(opt.gain||{});if(typeof opt.front==='number')S.fronts[opt.front]=Math.min(5,S.fronts[opt.front]+1);S.flags['council_'+ai]=index===0?'povo':'corte';log('CONSELHO · '+opt.report);closeModal();save();render()}
function showCouncil(){let event=COUNCILS[Math.floor((S.day-1)/6)];openModal(`<h2>${esc(event.title)}</h2><p class="story">${esc(event.story)}</p>${event.choices.map((q,i)=>`<button class="option" data-a="policy" data-v="${i}" ${hasCost(q.cost||{})?'':'disabled'}><strong>${esc(q.name)}</strong><span>${esc(q.desc)}</span></button>`).join('')}`)}
function renderPrep(){let evt=raid();return `<div class="eyebrow">A vigília de ${esc(evt.front)}</div><h2 class="section">Quem ficará no portão?</h2><div class="card important"><h3>${esc(evt.title)}</h3><p class="story">${esc(evt.story)}</p><div class="small">${esc(evt.hint)}</div></div><div class="card danger"><h3>⚠️ A aposta é definitiva</h3><p>Se os quatro enviados morrerem antes da vitória, a Rainha invadirá o reino e a campanha terminará. Personagens mortos não voltam ao reino. Use Cinza da Chama ou magia de ressurreição durante a luta para recuperar aliados caídos.</p></div><div class="boxline"><h3 class="subhead" style="margin:5px 0">Equipe de defesa</h3><span class="badge">${S.party.length}/4</span></div>${aliveHeroes().map(h=>heroMini(h,true)).join('')}<div class="btnrow"><button class="btn secondary" data-a="backprep">Voltar ao conselho</button><button class="btn" data-a="fight" ${S.party.length?'':'disabled'}>⚔️ Soar o sino</button></div>`}
function renderBattle(){let b=S.battle,evt=RAIDS[b.event-1];let current=b.active?hero(b.active):null;let activeName=current?current.name:'Turnos da Corte';
 let r=`<div class="battle-wrap"><div class="battle-header"><div class="phase-label">Dia ${S.day} · Rodada ${b.round} · ${esc(evt.front)}</div><h2 class="section">${esc(evt.title)}</h2><div class="small">${esc(evt.hint)}</div></div><div class="eyebrow">Hostes da Rainha da Noite</div><div class="enemy-grid">${b.foes.map(e=>`<button class="enemy-card ${e.hp<=0?'dead':''}" data-a="targetenemy" data-v="${e.uid}" ${e.hp<=0?'disabled':''}><span class="enemy-emoji">${e.icon}</span><span class="enemy-name">${esc(e.name)}</span><span class="tiny">PV ${e.hp}/${e.maxhp}${e.stage===2?' · FASE II':''}</span>${cssFill(e.hp,e.maxhp,'hp')}<span class="tiny">${statusCompact(e)}</span></button>`).join('')}</div><div class="eyebrow">Companhia de Thargrid</div><div class="battle-heroes">${b.party.map(id=>{let h=hero(id);return `<div class="fighter ${b.active===id?'current':''} ${h.hp<=0?'dead':''}"><div class="fighter-top"><span>${CLASSES[h.klass].icon}</span><strong>${esc(h.name.split(' ')[0])}</strong><span class="tiny">Nv ${h.level}</span></div><p>PV ${h.hp}/${maxHP(h)} · MP ${h.mp}/${maxMP(h)}</p>${cssFill(h.hp,maxHP(h),'hp')}${cssFill(h.mp,maxMP(h),'mp')}<p>${h.hp<=0?'CAÍDO · resgatável':statusCompact(h)||'Em combate'}${h.barrier?' · 🛡 '+h.barrier:''}</p></div>`}).join('')}</div><div class="combat-actions"><div class="turn-track">${current?'▶ Turno de '+esc(activeName):'A Corte está agindo'}</div><div class="btnrow"><button class="btn small" data-a="battleSkill" data-v="attack" ${current?'':'disabled'}>⚔️ Atacar</button><button class="btn small secondary" data-a="battleSkills" ${current?'':'disabled'}>✨ Magias e técnicas</button></div><div class="btnrow" style="margin-top:6px"><button class="btn small secondary" data-a="battleItems" ${current?'':'disabled'}>🎒 Itens</button><button class="btn small ghost" data-a="battleSkill" data-v="guard" ${current?'':'disabled'}>🛡 Defender</button></div></div><h3 class="subhead">Registro do combate</h3><div class="combat-log">${b.logs.slice(0,11).map(t=>`<div>${esc(t)}</div>`).join('')}</div></div>`;return r}
function statusCompact(x){return Object.keys(x.status||{}).map(v=>({burn:'🔥',poison:'☠',bleed:'🩸',stun:'💫',slow:'🐌',weak:'⬇ ATQ',atkUp:'⬆ ATQ',defUp:'⬆ DEF',mark:'🎯',regen:'💚'})[v]||v).join(' ')}
function renderAfter(){let reward=S.lastRewards||{reward:{},xp:0,dead:[],damage:0};let evt=raid();return `<div class="wrap"><div class="eyebrow">Dia ${S.day} de 60</div><h2 class="victory">A montanha resiste</h2><div class="card important"><h3>Vitória: ${esc(evt.title)}</h3><p class="story">${esc(evt.outcome||evt.story)}</p><p class="small">O ataque foi detido. Feridos ainda precisam de repouso; mortos não regressam por decreto.</p></div><div class="card"><h3>Despojos e aprendizado</h3><div class="chips">${Object.entries(reward.reward||{}).map(([k,v])=>`<span class="chip success">${RESN[k]?.[0]||k} +${v}</span>`).join('')}<span class="chip success">+${reward.xp} XP por sobrevivente</span></div>${reward.dead?.length?`<p class="bad">Tombaram: ${esc(reward.dead.join(', '))}</p>`:'<p class="good">Todos os enviados sobreviveram.</p>'}${reward.damage?`<p>O setor sofreu ${reward.damage} pontos de pressão de cerco. Reparos: ${fmtObj(reward.repair||{})}.</p>`:''}</div>${evt.boss?`<div class="card important"><h3>Fim do Ato ${evt.act+1}</h3><p class="story">${esc(ACTS[evt.act].ending)}</p></div>`:''}<button class="btn wide" data-a="nextday">${S.day<60?'Amanhecer do dia '+(S.day+1):'Concluir campanha de 60 dias'}</button></div>`}
function renderEnding(){let e=S.res.hope>60?'O Povo Sob a Montanha':S.res.hope>33?'A Montanha Inquebrável':'Uma Vitória Amarga';return `<div class="stage"><div class="hero-art">${mountainSVG()}<div class="banner-text">Thargrid<br>permanece.</div></div><div class="wrap"><div class="eyebrow">Sessenta dias de cerco</div><h2 class="section">${e}</h2><div class="card important"><p class="story">${S.res.hope>60?'As oficinas estão abertas, refugiados caminham livremente e a bandeira da resistência sobe acima dos muros. Os lordes descobriram que um reino não se mede apenas pelo tesouro dos nobres.':S.res.hope>33?'A Rainha recua diante da muralha. O preço da vitória aparece em leitos vazios e ferramentas gastas, mas os clãs permanecem juntos.':'A noite não levou a montanha. Entretanto, os sobreviventes ainda disputam comida e repouso. A vitória militar exige reconstrução social para virar liberdade.'}</p><p class="story">A Rainha da Noite não foi assassinada nem destruída. Seu assédio a Thargrid fracassou nesta campanha e sua ocupação da Carcaça ainda terá de ser enfrentada.</p></div><div class="chips"><span class="chip success">${S.victories} defesas vitoriosas</span><span class="chip">${S.casualties} mortos</span><span class="chip">${S.relics.length} relíquias</span><span class="chip">Moral ${S.res.hope}</span></div><div class="rule"></div><button class="btn wide" data-a="export">Exportar memória da campanha</button><button class="btn wide secondary" data-a="newconfirm" style="margin-top:9px">Começar uma nova resistência</button></div></div>`}
function renderGameover(){return `<div class="stage"><div class="hero-art" style="filter:saturate(.55)">${mountainSVG()}<div class="banner-text">A noite entrou.</div></div><div class="wrap"><div class="eyebrow bad">Thargrid foi invadida</div><h2 class="section">Fim da resistência</h2><div class="card danger"><p class="story">${esc(S.gameOverReason)}</p><p>A regra do cerco foi cumprida: todos os enviados morreram na batalha decisiva. Não há outro turno nem salvamento automático de recuperação.</p></div><div class="chips"><span class="chip">${S.victories} dias defendidos</span><span class="chip">${S.casualties} baixas</span></div><button class="btn wide secondary" data-a="export" style="margin-top:13px">Exportar registro da derrota</button><button class="btn wide red" data-a="newconfirm" style="margin-top:10px">Recomeçar campanha</button></div></div>`}
function mountainSVG(){return `<svg viewBox="0 0 440 240" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#182b3c"/><stop offset=".6" stop-color="#445565"/><stop offset="1" stop-color="#9b796a"/></linearGradient><linearGradient id="mount" x2="0" y2="1"><stop stop-color="#324352"/><stop offset="1" stop-color="#13212d"/></linearGradient></defs><rect width="440" height="240" fill="url(#sky)"/><circle cx="340" cy="50" r="29" fill="#d5c3a4" opacity=".7"/><path d="M0 178L45 130L96 159L148 80L208 155L280 44L350 128L405 70L440 121V240H0" fill="#50616a"/><path d="M126 112L148 80L174 117L148 104ZM257 75L280 44L305 76L279 65Z" fill="#c3d0ce" opacity=".8"/><path d="M0 213L71 145L121 194L190 130L247 184L340 114L440 190V240H0" fill="url(#mount)"/><path d="M44 240V183L83 165V151H105V129H127V163H147V117H183V165H203V143H223V177H254V104H278V84H310V109H328V178H352V140H384V183H413V240Z" fill="#0d1720"/><path d="M0 225H440" stroke="#cc9e70" opacity=".4"/><g fill="#edb87b" opacity=".65"><rect x="92" y="183" width="7" height="19"/><rect x="164" y="178" width="7" height="18"/><rect x="267" y="133" width="9" height="23"/><rect x="297" y="131" width="8" height="23"/><rect x="365" y="181" width="6" height="13"/></g></svg>`}
function renderTitle(){return `<div class="stage"><div class="hero-art">${mountainSVG()}<div class="banner-text">O Cerco<br>de Thargrid</div></div><div class="menu"><div class="eyebrow">O Reino Sob a Montanha · CARCAÇA</div><h1>60 noites para resistir.</h1><p>Construa as defesas de um povo sitiado. Faça seus heróis aprenderem, treinarem, conquistarem aliados e descobrirem a própria história. A Rainha da Noite atacará <strong>todos os dias</strong> — não importa quão feridos estejam seus defensores.</p><div class="card important"><div class="chips"><span class="chip">60 ataques narrativos</span><span class="chip">9 heróis possíveis</span><span class="chip">30 missões</span><span class="chip">6 artefatos lendários</span><span class="chip">Combate por turnos</span><span class="chip">Offline</span></div><p>Derrota definitiva se toda a equipe enviada à batalha morrer. Permadeath individual: mortos não retornam, exceto se reanimados durante o combate.</p></div><div class="eyebrow">Escolha a dificuldade</div><div class="seg"><button data-a="difficulty" data-v="story" class="${startDifficulty==='story'?'active':''}">Aprendiz</button><button data-a="difficulty" data-v="normal" class="${startDifficulty==='normal'?'active':''}">Cerco</button><button data-a="difficulty" data-v="hard" class="${startDifficulty==='hard'?'active':''}">Lenda</button></div><button class="btn" data-a="start">Iniciar resistência</button>${S?'<button class="btn secondary" data-a="continue">Continuar campanha salva</button>':''}<button class="btn ghost" data-a="import">Importar partida</button><div class="note" id="offline-note">${availableOffline?'✓ INSTALADO PARA USO OFFLINE':'Verificando disponibilidade offline...'} · Funciona sem internet após instalar a PWA.</div></div></div>`}
let startDifficulty='normal';let screen='title';
function render(){if(screen==='title'){document.querySelector('#app').className='app no-nav';$('app').innerHTML=renderTitle();return}
 if(!S)return;
 let page='',noNav=false;
 if(S.mode==='management'){page=hdr()+`<main class="wrap">${({council:renderCouncil,heroes:renderHeroes,quests:renderQuests,town:renderTown,codex:renderCodex})[S.tab]?.()||renderCouncil()}</main>`+nav()}
 else if(S.mode==='prep'){page=hdr()+`<main class="wrap">${renderPrep()}</main>`;noNav=true}
 else if(S.mode==='battle'){page=renderBattle();noNav=true}
 else if(S.mode==='aftermath'){page=renderAfter();noNav=true}
 else if(S.mode==='gameover'){page=renderGameover();noNav=true}
 else if(S.mode==='ending'){page=renderEnding();noNav=true}
 $('app').className='app '+(noNav?'no-nav':'');$('app').innerHTML=page;}
function openModal(content){$('modal').innerHTML=`<div class="sheet"><button class="modal-close" data-a="modalclose" aria-label="Fechar">✕</button>${content}</div>`}
function closeModal(){$('modal').innerHTML='';modalState=null}
function showHeroAction(id){let h=hero(id);if(!h)return;openModal(`<h2>${esc(h.name)}</h2><p class="small">Escolha uma atividade. Toda ação custa uma ordem do dia e só pode ser realizada por este herói uma vez no mesmo dia.</p><button class="option" data-a="traindlg" data-v="${id}"><strong>🏋️ Treinar atributos</strong><span>Força, defesa, velocidade, vigor ou concentração.</span></button><button class="option" data-a="studydlg" data-v="${id}"><strong>📖 Estudar magias e técnicas</strong><span>Pesquisa exige o Arquivo de Runas, mana e moedas.</span></button><button class="option" data-a="jobdlg" data-v="${id}"><strong>⚒️ Aprender ofício</strong><span>Forja, medicina, botânica, reconhecimento e outros.</span></button><button class="option" data-a="classdlg" data-v="${id}"><strong>🎭 Mudar classe</strong><span>Exige nível 3 e Oficinas dos Ofícios; classes são liberadas por encontros.</span></button><button class="option" data-a="treat" data-v="${id}"><strong>🩹 Tratamento intensivo</strong><span>Custa 1 erva, 14 moedas e 3 alimentos. Recupera PV, MP, fadiga e ferimentos.</span></button>`)}
function showTrain(id){let h=hero(id);let fields=[['atk','Força','Golpes físicos'],['def','Defesa','Diminui o dano sofrido'],['spd','Agilidade','Maior iniciativa'],['vit','Vigor','PV máximo'],['mag','Concentração','Magia e MP']];openModal(`<h2>Treinar: ${esc(h.name)}</h2><p class="small">Os atributos treinados crescem permanentemente. O treinamento gera cansaço, que permanece até a batalha desta noite.</p>${fields.map(([k,n,d])=>`<button class="option" data-a="train" data-v="${id}:${k}"><strong>${n} · ${h.training[k]||0}</strong><span>${d}. Custo: ${fmtObj({gold:8+(h.training[k]||0)*4,food:4})}</span></button>`).join('')}`)}
function showStudy(id){let h=hero(id);let options=Object.entries(SKILLS).filter(([k,sk])=>!['attack','guard'].includes(k)&&!h.learned.includes(k)&&(sk.type!=='physical'||CLASSES[h.klass].skills.includes(k))&&((sk.level||1)<=h.level));openModal(`<h2>Escola de ${esc(h.name)}</h2><p class="small">Conhecimento persistente: técnicas estudadas permanecem mesmo após a mudança de classe. Exige Arquivo de Runas. Nível do Arquivo: ${S.projects.library||0}.</p>${options.length?options.map(([k,sk])=>`<button class="option" data-a="study" data-v="${id}:${k}" ${(S.projects.library||0)?'':'disabled'}><strong>${esc(sk.name)} · ${sk.cost} MP</strong><span>${esc(sk.desc)} · custo de pesquisa ${fmtObj({mana:7+3*(sk.level||1),gold:12+2*(sk.level||1)})}</span></button>`).join(''):'<p class="small">Ainda não há novas técnicas compatíveis com seu nível. Continue lutando para desbloquear outras.</p>'}`)}
function showJobs(id){let h=hero(id);openModal(`<h2>Ofícios de ${esc(h.name)}</h2><p class="small">Aprender ou aprimorar ofícios melhora o desempenho em missões e a produção da cidade. Grau máximo: 3.</p>${PROFESSIONS.map(p=>`<button class="option" data-a="job" data-v="${id}:${p.id}" ${(h.professions[p.id]||0)>=3?'disabled':''}><strong>${p.icon} ${p.name} · Grau ${h.professions[p.id]||0}/3</strong><span>${esc(p.desc)} · custo: ${fmtObj({gold:16+(h.professions[p.id]||0)*12,food:5,mana:3})}</span></button>`).join('')}`)}
function showClass(id){let h=hero(id);openModal(`<h2>Nova classe para ${esc(h.name)}</h2><p class="small">As classes disponíveis são fruto de alianças, missões e estudo. Mudança exige nível 3, Oficinas dos Ofícios, 35 moedas e 12 essências.</p>${Object.entries(CLASSES).map(([k,c])=>`<button class="option" data-a="class" data-v="${id}:${k}" ${!S.unlocked.includes(k)||h.level<3||!(S.projects.guild||0)||h.klass===k?'disabled':''}><strong>${c.icon} ${c.name} ${S.unlocked.includes(k)?'':'🔒'}</strong><span>${k===h.klass?'Classe atual':c.skills.map(s=>SKILLS[s]?.name).join(', ')}</span></button>`).join('')}`)}
function showDetail(id){let h=hero(id);if(!h)return;let c=CLASSES[h.klass];openModal(`<h2>${c.icon} ${esc(h.name)}</h2><p class="story">${esc(h.bio)}</p><div class="chips"><span class="chip">Nível ${h.level}</span><span class="chip">${esc(c.name)}</span><span class="chip">${statusText(h)||'Vivo'}</span></div><div class="statgrid" style="margin:10px 0">${[['ATQ','atk'],['MAG','mag'],['DEF','def'],['VEL','spd']].map(([n,k])=>`<div class="stat">${n}<strong>${stat(h,k)}</strong></div>`).join('')}</div><div class="metric-label"><span>PV ${h.hp}/${maxHP(h)}</span><span>MP ${h.mp}/${maxMP(h)}</span></div><h3>Magias e técnicas</h3><div class="small">${[...new Set([...h.learned,...c.skills.filter(id=>h.level>=(SKILLS[id].level||1))])].map(k=>esc(SKILLS[k]?.name||k)).join(' · ')}</div><h3>Ofícios</h3><div class="small">${Object.entries(h.professions).map(([k,n])=>`${PROFESSIONS.find(p=>p.id===k)?.name||k} ${n}`).join(' · ')}</div><p class="small">Experiência ${h.xp}/${xpNeed(h.level)} · treinamento de força ${h.training.atk}, magia ${h.training.mag}, defesa ${h.training.def}, velocidade ${h.training.spd}, vigor ${h.training.vit}.</p>`)}
function showQuest(id){let q=QUESTS.find(x=>x.id===id);if(!q)return;let choices=aliveHeroes().filter(h=>!h.used&&h.fatigue<=89&&(!q.hero||q.hero===h.id));openModal(`<h2>${esc(q.title)}</h2><p class="story">${esc(q.desc)}</p><p class="small">Risco de ferimento: ${q.risk}. Exaustão: +${q.fatigue}. Recompensas: ${fmtObj(q.reward)}. O herói retorna antes da batalha desta noite.</p><div class="eyebrow">Escolha o expedicionário</div>${choices.map(h=>`<button class="option" data-a="quest" data-v="${id}:${h.id}"><strong>${CLASSES[h.klass].icon} ${esc(h.name)} · Nv ${h.level}</strong><span>PV ${h.hp} · Cansaço ${h.fatigue}% · ${esc(CLASSES[h.klass].name)}</span></button>`).join('')||'<p class="bad">Nenhum herói disponível para esta expedição.</p>'}`)}
function showBattleSkills(){const b=S.battle;if(!b||!b.active)return;let h=hero(b.active),c=CLASSES[h.klass];let options=[...new Set([...h.learned,...c.skills.filter(k=>h.level>=(SKILLS[k].level||1))])].filter(k=>SKILLS[k]);openModal(`<h2>Magias e técnicas</h2><p class="small">${esc(h.name)} · ${h.mp}/${maxMP(h)} MP. O turno só termina após lançar uma habilidade ou utilizar um item.</p>${options.map(id=>{let s=SKILLS[id];return `<button class="option" data-a="battleSkill" data-v="${id}" ${s.cost>h.mp?'disabled':''}><strong>${esc(s.name)} · ${s.cost} MP</strong><span>${esc(s.desc)}</span></button>`}).join('')}`)}
function showCombatItems(){if(!S.battle?.active)return;openModal(`<h2>Bolsa de combate</h2>${Object.entries(STORE).map(([k,o])=>`<button class="option" data-a="battleItem" data-v="${k}" ${(S.inventory[k]||0)<=0?'disabled':''}><strong>${esc(o.name)} ×${S.inventory[k]||0}</strong><span>${esc(o.desc)}</span></button>`).join('')}`)}
function showTargets(kind,skill){const b=S.battle;if(!b||!b.active)return;let sk=kind==='skill'?SKILLS[skill]:null;let type=sk?.target||(skill==='phoenix'?'fallen':'ally');if(type==='allEnemies'||type==='allAllies'||type==='self'){if(kind==='skill')doSkill(skill,null);return}
 const opts=type==='enemy'?b.foes.filter(e=>e.hp>0).map(e=>({id:e.uid,label:`${e.icon} ${e.name}`,detail:`PV ${e.hp}/${e.maxhp}`})):b.party.map(id=>hero(id)).filter(h=>type==='fallen'?h.hp<=0:h.hp>0).map(h=>({id:h.id,label:`${CLASSES[h.klass].icon} ${h.name}`,detail:`PV ${h.hp}/${maxHP(h)} · MP ${h.mp}`}));
 if(!opts.length){notify('Não há alvo apropriado.');return}
 openModal(`<h2>Escolha o alvo</h2><p class="small">${kind==='skill'?SKILLS[skill].name:STORE[skill].name}</p>${opts.map(o=>`<button class="option" data-a="perform" data-v="${kind}:${skill}:${o.id}"><strong>${esc(o.label)}</strong><span>${esc(o.detail)}</span></button>`).join('')}`)}
function triggerExport(){let blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`thargrid-dia-${S.day}-save.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Save exportado como arquivo JSON.')}
function triggerImport(){let inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.onchange=()=>{let file=inp.files?.[0];if(!file)return;file.text().then(t=>{let obj=JSON.parse(t);if(obj.version!==1||!obj.heroes||!obj.res||!obj.fronts||!Number.isInteger(obj.day)||obj.day<1||obj.day>60)throw Error('Save inválido.');S=obj;screen='game';save();closeModal();render();notify('Save importado.')}).catch(e=>notify('Não foi possível importar: '+e.message))};inp.click()}
function confirmReset(){openModal(`<h2>Começar uma nova campanha?</h2><p>Isso substituirá o progresso salvo automaticamente neste navegador. Exporte o save atual antes de confirmar se quiser preservá-lo.</p><div class="btnrow"><button class="btn red" data-a="newgame">Apagar e reiniciar</button><button class="btn secondary" data-a="modalclose">Cancelar</button></div>`)}
function handle(a,v){switch(a){
 case 'start':S=fresh(startDifficulty);screen='game';save();render();break;
 case 'continue':if(S){screen='game';render()}break;
 case 'difficulty':startDifficulty=v;render();break;
 case 'tab':goTab(v);break;
 case 'prepare':if((S.day-1)%6===0&&!S.flags['council_'+Math.floor((S.day-1)/6)])return notify('Delibere primeiro no Conselho, no alto da tela.');S.mode='prep';render();break;
 case 'council':showCouncil();break;
 case 'policy':decideCouncil(Number(v));break;
 case 'backprep':S.mode='management';render();break;
 case 'fight':beginBattle();break;
 case 'party':chooseParty(v);break;
 case 'construct':construct(v);break;
 case 'front':reinforce(Number(v));break;
 case 'buy':buyItem(v);break;
 case 'heroaction':showHeroAction(v);break;
 case 'herodetail':showDetail(v);break;
 case 'traindlg':showTrain(v);break;
 case 'studydlg':showStudy(v);break;
 case 'jobdlg':showJobs(v);break;
 case 'classdlg':showClass(v);break;
 case 'train':train(...v.split(':'));break;
 case 'study':study(...v.split(':'));break;
 case 'job':learnJob(...v.split(':'));break;
 case 'class':switchClass(...v.split(':'));break;
 case 'treat':treat(v);break;
 case 'questopen':showQuest(v);break;
 case 'quest':questRun(...v.split(':'));break;
 case 'battleSkills':showBattleSkills();break;
 case 'battleItems':showCombatItems();break;
 case 'battleSkill':showTargets('skill',v);break;
 case 'targetenemy':if(S.battle?.active)doSkill('attack',v);break;
 case 'battleItem':showTargets('item',v);break;
 case 'perform':{const [kind,skill,target]=v.split(':');if(kind==='skill')doSkill(skill,target);else useCombatItem(skill,target);break}
 case 'nextday':nextDay();break;
 case 'modalclose':closeModal();break;
 case 'export':triggerExport();break;
 case 'import':triggerImport();break;
 case 'newconfirm':confirmReset();break;
 case 'newgame':S=fresh(S?.difficulty||startDifficulty);screen='game';save();closeModal();render();break;
 }}
document.addEventListener('click',e=>{const bt=e.target.closest('[data-a]');if(!bt||bt.disabled)return;let a=bt.dataset.a,v=bt.dataset.v||'';try{handle(a,v)}catch(err){console.error(err);notify('Erro detectado: '+err.message)}});
function registerOffline(){if(IS_PHASER_PREVIEW||!('serviceWorker' in navigator)){return}navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(async r=>{await navigator.serviceWorker.ready;let cache=await caches.open('thargrid-pwa-v1.0.7');const required=['./','./index.html','./style.css','./data.js','./core/combat.js','./core/actions.js','./core/effects.js','./app.js','./manifest.webmanifest','./icons/icon-192.png','./icons/icon-512.png'];let ready=(await Promise.all(required.map(s=>cache.match(new URL(s,location.href))))).every(Boolean);availableOffline=ready;let el=document.querySelector('#offline-note');if(el&&ready)el.textContent='✓ INSTALADO PARA USO OFFLINE · O app já pode funcionar sem internet.'}).catch(e=>console.warn('offline',e))}
load();render();registerOffline();
